package com.aaliyun.leadnews.behavior.mapper;
import com.aaliyun.leadnews.model.behavior.BehaviorEvent;import org.apache.ibatis.annotations.*;import java.util.*;
@Mapper public interface BehaviorMapper {
 @Insert("INSERT IGNORE INTO behavior_event_log(event_id,article_id,user_id,behavior_type,delta_value,occurred_at,stat_applied) VALUES(#{eventId},#{articleId},#{userId},#{behaviorType},#{delta},#{occurredAt},IF(#{behaviorType}='VIEW',0,1))") int insertEvent(BehaviorEvent e);
 @Insert("INSERT INTO article_behavior_stat(article_id,like_count,view_count) VALUES(#{articleId},GREATEST(#{likeDelta},0),GREATEST(#{viewDelta},0)) ON DUPLICATE KEY UPDATE like_count=GREATEST(like_count+#{likeDelta},0),view_count=GREATEST(view_count+#{viewDelta},0)") int addStat(@Param("articleId")long articleId,@Param("likeDelta")long likeDelta,@Param("viewDelta")long viewDelta);
 @Insert("INSERT INTO article_like(article_id,user_id,status) VALUES(#{articleId},#{userId},#{status}) ON DUPLICATE KEY UPDATE status=#{status},updated_time=CURRENT_TIMESTAMP(3)") int saveLike(@Param("articleId")long articleId,@Param("userId")long userId,@Param("status")int status);
 @Insert("INSERT IGNORE INTO consumed_event(consumer_group,event_id,event_type,article_id) VALUES(#{group},#{eventId},#{type},#{articleId})") int claimConsumed(@Param("group")String group,@Param("eventId")String eventId,@Param("type")String type,@Param("articleId")long articleId);
 @Insert("INSERT IGNORE INTO article_behavior_stat(article_id) VALUES(#{articleId})") int ensureStat(@Param("articleId")long articleId);
 @Select("SELECT like_count FROM article_behavior_stat WHERE article_id=#{articleId} FOR UPDATE") Long lockLikeCount(@Param("articleId")long articleId);
 @Select("SELECT status,relation_version relationVersion FROM article_like WHERE article_id=#{articleId} AND user_id=#{userId}") Map<String,Object> likeRelation(@Param("articleId")long articleId,@Param("userId")long userId);
 @Insert("INSERT INTO article_like(article_id,user_id,status,relation_version) VALUES(#{articleId},#{userId},#{status},#{version}) ON DUPLICATE KEY UPDATE status=IF(relation_version<VALUES(relation_version),VALUES(status),status),relation_version=GREATEST(relation_version,VALUES(relation_version))") int saveVersionedLike(@Param("articleId")long articleId,@Param("userId")long userId,@Param("status")int status,@Param("version")long version);
 @Update("UPDATE article_behavior_stat SET like_count=GREATEST(0,like_count+#{delta}) WHERE article_id=#{articleId}") int changeLikeStat(@Param("articleId")long articleId,@Param("delta")int delta);
 @Update("UPDATE article_behavior_stat SET like_count=IF(like_count_version<#{version},#{count},like_count),like_count_version=GREATEST(like_count_version,#{version}) WHERE article_id=#{articleId}") int saveLikeCountVersioned(@Param("articleId")long articleId,@Param("count")long count,@Param("version")long version);
 @Select("SELECT collect_count FROM article_behavior_stat WHERE article_id=#{articleId} FOR UPDATE") Long lockCollectCount(@Param("articleId")long articleId);
 @Select("SELECT status,relation_version relationVersion FROM article_collect WHERE article_id=#{articleId} AND user_id=#{userId}") Map<String,Object> collectRelation(@Param("articleId")long articleId,@Param("userId")long userId);
 @Insert("INSERT INTO article_collect(article_id,user_id,status,relation_version) VALUES(#{articleId},#{userId},#{status},#{version}) ON DUPLICATE KEY UPDATE status=IF(relation_version<VALUES(relation_version),VALUES(status),status),relation_version=GREATEST(relation_version,VALUES(relation_version))") int saveVersionedCollect(@Param("articleId")long articleId,@Param("userId")long userId,@Param("status")int status,@Param("version")long version);
 @Update("UPDATE article_behavior_stat SET collect_count=GREATEST(0,collect_count+#{delta}) WHERE article_id=#{articleId}") int changeCollectStat(@Param("articleId")long articleId,@Param("delta")int delta);
 @Update("UPDATE article_behavior_stat SET collect_count=IF(collect_count_version<#{version},#{count},collect_count),collect_count_version=GREATEST(collect_count_version,#{version}) WHERE article_id=#{articleId}") int saveCollectCountVersioned(@Param("articleId")long articleId,@Param("count")long count,@Param("version")long version);
 @Delete("DELETE FROM consumed_event WHERE consumed_time<#{cutoff} ORDER BY consumed_time LIMIT #{limit}") int purgeConsumed(@Param("cutoff")java.time.LocalDateTime cutoff,@Param("limit")int limit);
 @Select("SELECT like_count likeCount,view_count viewCount,comment_count commentCount,collect_count collectCount,like_count_version likeCountVersion,collect_count_version collectCountVersion FROM article_behavior_stat WHERE article_id=#{id}") Map<String,Object> stat(long id);
 @Select("SELECT article_id articleId,like_count likeCount,view_count viewCount,comment_count commentCount,collect_count collectCount FROM article_behavior_stat ORDER BY updated_time DESC LIMIT #{limit}") List<Map<String,Object>> recentStats(int limit);
 @Select("SELECT status FROM article_like WHERE article_id=#{articleId} AND user_id=#{userId}") Integer likeStatus(@Param("articleId")long articleId,@Param("userId")long userId);
 @Insert("INSERT INTO behavior_failed_event(event_id,article_id,payload,error_message) VALUES(#{eventId},#{articleId},#{payload},#{error})") int failed(@Param("eventId")String eventId,@Param("articleId")Long articleId,@Param("payload")String payload,@Param("error")String error);
 @Select("SELECT id,article_id articleId,delta_value delta FROM behavior_event_log WHERE behavior_type='VIEW' AND stat_applied=0 ORDER BY id LIMIT 1000 FOR UPDATE") List<Map<String,Object>> pendingViews();
 @Update("<script>UPDATE behavior_event_log SET stat_applied=1 WHERE id IN <foreach collection='ids' item='id' open='(' separator=',' close=')'>#{id}</foreach></script>") int markApplied(@Param("ids")List<Long> ids);
 @Insert("INSERT INTO hot_score_checkpoint(article_id,channel_id,hot_score,snapshot_time) VALUES(#{articleId},#{channelId},#{score},CURRENT_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE channel_id=VALUES(channel_id),hot_score=VALUES(hot_score),snapshot_time=VALUES(snapshot_time)") int saveHotCheckpoint(@Param("articleId")long articleId,@Param("channelId")long channelId,@Param("score")double score);
 @Select("SELECT article_id articleId,channel_id channelId,hot_score hotScore FROM hot_score_checkpoint ORDER BY hot_score DESC LIMIT #{limit}") List<Map<String,Object>> hotCheckpoints(@Param("limit")int limit);
 @Insert("INSERT INTO article_hot_snapshot(snapshot_id,article_id,channel_id,hot_score,like_count,collect_count,comment_count,view_count,snapshot_time) VALUES(#{snapshotId},#{articleId},#{channelId},#{score},#{likeCount},#{collectCount},#{commentCount},#{viewCount},#{snapshotTime})") int insertHotSnapshot(@Param("snapshotId")String snapshotId,@Param("articleId")long articleId,@Param("channelId")long channelId,@Param("score")double score,@Param("likeCount")long likeCount,@Param("collectCount")long collectCount,@Param("commentCount")long commentCount,@Param("viewCount")long viewCount,@Param("snapshotTime")java.time.LocalDateTime snapshotTime);
 @Insert("INSERT INTO article_hot_snapshot_batch(snapshot_id,snapshot_time,status) VALUES(#{snapshotId},#{snapshotTime},'BUILDING')") int startHotSnapshot(@Param("snapshotId")String snapshotId,@Param("snapshotTime")java.time.LocalDateTime snapshotTime);
 @Update("UPDATE article_hot_snapshot_batch SET status='COMPLETE',article_count=#{count} WHERE snapshot_id=#{snapshotId} AND status='BUILDING'") int completeHotSnapshot(@Param("snapshotId")String snapshotId,@Param("count")int count);
 @Select("SELECT snapshot_id FROM article_hot_snapshot_batch WHERE status='COMPLETE' ORDER BY snapshot_time DESC LIMIT 1") String latestHotSnapshotId();
 @Select("SELECT id,snapshot_id snapshotId,article_id articleId,channel_id channelId,hot_score hotScore,like_count likeCount,collect_count collectCount,comment_count commentCount,view_count viewCount,snapshot_time snapshotTime FROM article_hot_snapshot WHERE snapshot_id=#{snapshotId} AND id>#{afterId} ORDER BY id LIMIT #{limit}") List<Map<String,Object>> hotSnapshotPage(@Param("snapshotId")String snapshotId,@Param("afterId")long afterId,@Param("limit")int limit);
 @Delete("DELETE FROM article_hot_snapshot WHERE snapshot_time<#{cutoff} ORDER BY snapshot_time LIMIT #{limit}") int purgeHotSnapshots(@Param("cutoff")java.time.LocalDateTime cutoff,@Param("limit")int limit);
 @Delete("DELETE FROM article_hot_snapshot_batch WHERE snapshot_time<#{cutoff} LIMIT #{limit}") int purgeHotSnapshotBatches(@Param("cutoff")java.time.LocalDateTime cutoff,@Param("limit")int limit);
}
